test('invoiceTotals calculates subtotal, discount, vat and total for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'HOST-MONTH', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500 + 3 * 9500 + 1 * 1500;
  assert.equal(subtotal, 47000);
  assert.equal(totals.subtotal, 47000);
  assert.equal(totals.discount, 2350);
  assert.equal(totals.vat, 8939);
  assert.equal(totals.total, 53589);
});

